(function() {
    "use strict";

    var dataLayerEnabled;
    var dataLayer;

    function addComponentToDataLayer(component) {
        dataLayer.push({
            component: getComponentObject(component)
        });
    }

    function attachClickEventListener(element) {
        element.addEventListener("click", addClickToDataLayer);
    }

    function getComponentObject(element) {
        var component = getComponentData(element);
        var componentID = Object.keys(component)[0];
        // if the component does not have a parent ID property, use the ID of the parent element
        if (component && component[componentID] && !component[componentID].parentId) {
            var parentElement = element.parentNode.closest("[data-cmp-data-layer], body");
            if (parentElement) {
                component[componentID].parentId = parentElement.id;
            }
        }

        return component;
    }

    function addClickToDataLayer(event) {
        var element = event.currentTarget;
        var componentId = getClickId(element);

        dataLayer.push({
            event: "cmp:click",
            eventInfo: {
                path: "component." + componentId
            }
        });
    }

    function getComponentData(element) {
        var dataLayerJson = element.dataset.cmpDataLayer;
        if (dataLayerJson) {
            return JSON.parse(dataLayerJson);
        } else {
            return undefined;
        }
    }

    function getClickId(element) {
        if (element.dataset.cmpDataLayer) {
            return Object.keys(JSON.parse(element.dataset.cmpDataLayer))[0];
        }

        var componentElement = element.closest("[data-cmp-data-layer]");

        return Object.keys(JSON.parse(componentElement.dataset.cmpDataLayer))[0];
    }

    function onDocumentReady() {
        dataLayerEnabled = document.body.hasAttribute("data-cmp-data-layer-enabled");
        dataLayer        = (dataLayerEnabled) ? window.adobeDataLayer = window.adobeDataLayer || [] : undefined;

        if (dataLayerEnabled) {

            var components        = document.querySelectorAll("[data-cmp-data-layer]");
            var clickableElements = document.querySelectorAll("[data-cmp-clickable]");

            components.forEach(function(component) {
                addComponentToDataLayer(component);
            });

            clickableElements.forEach(function(element) {
                attachClickEventListener(element);
            });

            dataLayer.push({
                event: "cmp:loaded"
            });
        }
    }

    if (document.readyState !== "loading") {
        onDocumentReady();
    } else {
        document.addEventListener("DOMContentLoaded", onDocumentReady);
    }

}());


window.onscroll = () => {
if(document.getElementsByClassName("scrollabletabs").length>0)
    {
        let tablist = document.getElementsByClassName("cmp-tabs__tablist");
        for(let i = 0;  i < tablist.length; i++){
            let tabnav = tablist[i];
            let position = tabnav.parentElement.offsetTop;
            if(window.pageYOffset >= position) {
                tablist[i].classList.add("cmp-tabs__sticky");
            } else {
                tablist[i].classList.remove("cmp-tabs__sticky");
            }            
        }

    }    
}

let pageNo = 1;
let pageTotal = 1;

// const getCurrentPageNumber = () => {
//     let currentPage = document.querySelector("cmp-pagination__selected") ? document.querySelector("cmp-pagination__selected").textContent : 1;
//     console.log("Current Page: " + currentPage);
//     return Number.parseInt(currentPage);
// }

// Async Function to load promise from makeRequest Function
async function performAjaxRequest(method, url) {
    // await code here
    let result = await makeAjaxRequest(method, url);

    return result;
}

// Function that actually calls the server to make the search query
function makeAjaxRequest(method, url) {
    return new Promise(function (resolve, reject) {
        let request = new XMLHttpRequest();
        request.open(method, url);

        const queryString = window.location.search;

        const urlParams = new URLSearchParams(queryString);

        for (const entry of urlParams.entries()) {

            request.setRequestHeader(entry[0], entry[1]);

        }

        request.setRequestHeader("pageNumber", pageNo);

        // Onload just executes a callback once request completes successfully
        request.onload = function () {
            if (this.status >= 200 && this.status < 300) {
                resolve(JSON.parse(request.response));
            } else {
                reject({
                    status: this.status,
                    statusText: request.statusText
                });
            }
        };
        request.onerror = function () {
            reject({
                status: this.status,
                statusText: request.statusText
            });
        };
        request.send();
    });
}

const generateNewsArticle = () => {

    const cmpNewsListingFilter = document.getElementById("cmp-news-listing-filter");
    const resultsPerPage = cmpNewsListingFilter.getAttribute("results-per-page");
    const resourcePath = cmpNewsListingFilter.getAttribute("resource-path");

    const result = performAjaxRequest("GET", 
        `${window.location.origin}${resourcePath}.newslistingexporter.json`);

    result.then(data => {

        console.log(data);

        const articleInformation = data.articleInformation;

        const totalResults = Number.parseInt(articleInformation.resultNumber);
        const articles = articleInformation.articles;

        let newslisting = document.getElementById("newsListings");
        while (newslisting.firstChild) {
            newslisting.removeChild(newslisting.firstChild);
        }

        let newItem;
        //iterate through/append articles
        for(index in articles) {
            let item = articles[index];
            newItem = document.createElement("li");
            newItem.classList.add("headline__item");
            let title = item["title"];
            let body = item["body"];
            let date = item["dateAndTime"];
            let link = item["path"] + ".html";
            let longerThanDesc = item["longerThanDescriptionCharLimit"];

            let header = document.createElement("h3");
            header.innerText = title;
            header.classList.add("cmp-list__news-title");

            let dateParagraph = document.createElement("p");
            dateParagraph.innerText = date;
            dateParagraph.classList.add("cmp-list__news-date");

            let bodyParagraph = document.createElement("div");
            bodyParagraph.innerHTML = body;
            
            console.log(longerThanDesc);

            if (longerThanDesc) {

                console.log("Creating More Link");
                let moreButton = document.createElement("span");
                moreButton.innerText=" MORE";
                moreButton.classList.add("cmp-list__news-more-link");
                bodyParagraph.appendChild(moreButton);
            }
            
            bodyParagraph.classList.add("cmp-list__news-description");

            let article = document.createElement("a");
            article.setAttribute("href",link);
            article.appendChild(header);
            article.appendChild(dateParagraph);
            article.appendChild(bodyParagraph);

            newItem.appendChild(article);
            newItem.classList.add("cmp-list__news-item");

            newslisting.appendChild(newItem);
        }

        newsListingPagination(totalResults, resultsPerPage);

    });
            
}

// dynamically populate pagination/page numbers list
const newsListingPagination = (totalResults, resultsPerPage) => {
    let totalPages = Math.ceil(totalResults / resultsPerPage);
    pageTotal = Number.parseInt(totalPages);
    //console.log("Generate " + pageTotal +  " pages starting from page " + pageNo);

    let pageUpperLimit = pageNo;
    let pageLowerLimit = pageNo;

    //console.log("(before) lower: " + pageLowerLimit + " upper: " + pageUpperLimit);

    let isOnly = pageTotal<=4; 
    let isBetween = pageNo<(pageTotal-3) && pageTotal > 4;
    if(isOnly) {
        //4 pages or less of results
        pageLowerLimit = 1;
        pageUpperLimit = pageTotal;
    }
    else if (isBetween) { 
        //if upper limit is the total pages, then display page options for last 3 pages
        pageLowerLimit = pageNo;
        pageUpperLimit = pageNo+3;
    } else if (pageNo >= (pageTotal-3)) {
        pageLowerLimit = pageTotal-3;
        pageUpperLimit = pageTotal;
    }

    let div = document.getElementById("newsListingsPagination");
    div.classList.add("cmp-pagination__container");
    while(div.firstChild)
    {
        div.removeChild(div.firstChild);
    }

    //console.log("(after) lower: " + pageLowerLimit + " upper: " + pageUpperLimit);
    
    //insert pagination. show only 4 pages
    for(let i=pageLowerLimit; i<=pageUpperLimit;i++) {
        let a = document.createElement("a");
        let textNode = document.createTextNode(i);
        
        a.appendChild(textNode);
        //check if page selected
        if(i==pageNo){
            a.classList.add("cmp-pagination__selected");
            a.classList.remove("cmp-pagination__link");
            
        } else {
            a.classList.remove("cmp-pagination__selected");
            a.classList.add("cmp-pagination__link");
        }

        div.appendChild(a);
    }

    //add first, prev, next, last
    let first =  document.createElement("a");
    let textNode = document.createTextNode("first");
    first.classList.add("cmp-pagination__link");
    first.appendChild(textNode);

    let prev = document.createElement("a");
    textNode = document.createTextNode("prev");
    prev.classList.add("cmp-pagination__link");
    prev.appendChild(textNode);

    let next = document.createElement("a");
    textNode = document.createTextNode("next");
    next.classList.add("cmp-pagination__link");
    next.appendChild(textNode);
    
    let last = document.createElement("a");
    textNode = document.createTextNode("last");
    last.classList.add("cmp-pagination__link");
    last.appendChild(textNode);

    let ellipses = document.createElement("a");
    textNode = document.createTextNode("...");
    ellipses.appendChild(textNode);

    if(totalResults>0){
        if(pageNo > 1 && pageNo < pageTotal){
            //display both first/prev and next/last        
            let ellipsesbefore = document.createElement("a");
            textNode = document.createTextNode("...");
            ellipsesbefore.appendChild(textNode);

            if(pageLowerLimit!=1){
                div.prepend(ellipsesbefore);
            }
            div.prepend(prev);
            div.prepend(first);
            
            if(pageUpperLimit!=pageTotal){
                div.append(ellipses);
            }
            div.append(next);
            div.append(last);
        } else if (pageNo == 1 && pageNo == pageTotal){
            //only one page of result
            //do not display first/prev or next/last
        } else if (pageNo == 1) {
            //display only next/last
            if(pageUpperLimit!=pageTotal){
                div.append(ellipses);
            }
            div.append(next);
            div.append(last);
        } else if(pageNo == pageTotal) {
            //display only first/prev
            if(pageLowerLimit!=1){
                div.prepend(ellipses);
            }
            div.prepend(prev);
            div.prepend(first);       
        }
    }
}

//listen for pagination and return results
if(document.getElementsByClassName("cmp-list__news-listing-filter").length > 0){
    document.getElementById("newsListingsPagination").addEventListener("click", function(event){
        const target = event.target;
        //console.log("event.target: " + target.textContent);
        let pageSelected = target.textContent;
    
        switch(target.textContent){
            case "first": pageSelected = 1;
            break;        
            case "prev": pageSelected = pageNo - 1;
            break;        
            case "next": pageSelected = pageNo + 1;
            break;        
            case "last": pageSelected = pageTotal;
            break;
            default: break;
        }
        let currentPage = pageNo;
        pageNo = String(pageSelected).includes("...") ? pageNo : Number.parseInt(pageSelected);
        if(pageNo==currentPage){
            return;
        } else {
            console.log("page selected: " + pageNo);
            generateNewsArticle(); 
        }
    }); 
}

