const getSelectedCategoryForDropdown = () => {
 
    const selectedCategory = document.getElementById("newslisting-category").value;
 
    const queryString = window.location.search;
 
    const urlParams = new URLSearchParams(queryString);
 
    let currentpath = window.location.pathname + "?";
 
    if (urlParams.keys().next().value && urlParams.keys().next().value !== "wcmmode") {
 
        const entries = urlParams.entries();
 
        for (var entry of entries) {
 
            if (entry[0] !== "category") {
 
                currentpath += entry[0] + "=" + entry[1] + "&";
 
            }
 
        }
 
        currentpath += "category=" + selectedCategory
 
    } else {
 
        currentpath += "category=" + selectedCategory
 
    }
 
    window.location.assign(currentpath);
 
}
