/**
 * Simple router/controller that will kick off the init script for the current page.
 * At present, it grabs the 'data-route' attribute on the body tag and executes that route.
 * For example, if data-route="home", the executeRoute method will call APP.home.init()
 */

'use strict';

var APP = window.APP = window.APP || {};

APP.core = {};

APP.core.controller = (function(){

    //private variable
    var _routes = [];

    var addRoute = function(strVal) {
        _routes.push(strVal);
    };

    var setRoutes = function(routes) {
        _routes = routes;
    };

    var getRoutes = function() {
        return _routes;
    };

    var executeRoutes = function() {
        var ns = APP;
        var routes = getRoutes();
        var action = 'init';
        if (routes && routes.length > 0) {
            for (var i=0; i<routes.length; i++) {
                var route = routes[i];
                if (route !== '' && ns[route] && typeof ns[route][action] === 'function') {
                    console.log('APP.controller.init | route name = ' + route);
                    ns[route][action]();
                }
            }
        }
    };

    // exposed methods will be prefixed with the word `public`
    var init = function() {

        console.log('APP.controller.init');
	 var routeName;
        //This way is supported by IE8
      //  var routeName = document.querySelectorAll('.js-page-controller-action')[0].getAttribute('data-action-name');
        //var routeName = document.getElementsByClassName('js-page-controller-action')[0].getAttribute('data-action-name');
        
        if (routeName) {
            if (routeName.indexOf(' ') > -1) {
                setRoutes(routeName.split(' '));
            } else {
                addRoute(routeName);
            }
        }
        executeRoutes();
    };

    /**
    * interfaces to public functions
    */
    return {
        init: init
    };

}());

'use strict';

var APP = window.APP = window.APP || {};

APP.global = (function(){
    var isFirstVisit = true;
    var shouldPush = true;
    var isWindowPopped = false;

    var initGlobalComponents = function() {
        APP.thankYouOverlay.init();
        APP.contactOverlayCaptcha.init();
		APP.licensingApplication.init();
        APP.requestPrintOverlayCaptcha.init();
        APP.sponsorshipRequestForm.init();
        APP.newsAlerts.init();
        APP.unsubscribe.init();
    };

    var initPageComponents = function() {
        APP.core.controller.init();
    };

    var setBlurHeight = function(){
        if($('.masthead')){
            var height = $('.masthead__container').height()+138;
            $('.js-page-blur').css('height',height);
        }
    };

    var checkBackgroundBlendMode = function(){
        if(!$('body').hasClass('lt-ie9') ) {
            var supportsBackgroundBlendMode = window.getComputedStyle(document.body).backgroundBlendMode;
            if(supportsBackgroundBlendMode){
                $('html').addClass('backgroundblendmode');
            }
        };
    };

    var goBackHistory = function(){
        $('.wingfoot-express, .charles-goodyear-story, .beginnings, .wingfoot-origin').find('.cta').click(function(e) {
            if (document.referrer.search('/en-US/about/history.html') !== -1) {
                e.preventDefault();
                window.history.back();
                console.log('yes');
            }
        });
    };

 /*   var initPagination = function(index){
        $('.js-pagination').jPages({
            containerID  : 'gy-pagination-items',
            perPage      : 10,
            next         : 'Next',
            previous     : 'Prev',
            first        : 'First',
            last         : 'Last',
            startPage    : index,
            startRange   : 0,
            midRange     : 4,
            endRange     : 0,
            fallback     : 150,
            minHeight    : false,
            callback: function(pages, items){
                //console.log('shouldPush = ' +shouldPush);
                if(pages.count > 1){
                    $('#js-pagination-legend').html(items.range.start + ' - ' + items.range.end + ' of ' + items.count); //21 - 30 of 138
                    if(pages.current > 1){
                        $('html,body').animate({scrollTop: $('#gy-pagination-items').offset().top - 40}, 'slow');
                    }
                }else{
                    $('.js-pagination').css('display','none');
                }

                if (!(XMLHttpRequest) && shouldPush) { // ie's having problems with this
                    var pageNum = pages.current;

                    if(!isFirstVisit){
                        history.pushState({page: pageNum}, '', '');
                        // console.log('push '+pageNum);
                    } else {
                        if(!history.state){
                            history.replaceState({page: pageNum}, '', '');
                            // console.log('replace '+pageNum);
                        }
                        isFirstVisit = false;
                    }
                }
                shouldPush = true;
            }
        });

    }; */

    var bindEventsToUI = function() {
        if (!(XMLHttpRequest)) { // ie's having problems with this
            window.onpopstate = function(event) {
                var index = 1;
                //console.log('window popped = ' + isWindowPopped);
                if($('.js-pagination')){
                    if(!isFirstVisit){
                        isWindowPopped = true;
                    }
                    if(history.state !== null){
                        index = history.state.page;
                    }
                    if(isWindowPopped){
                        shouldPush = false;
                    }
                    $('.js-pagination').jPages(index);
                    //console.log('pop ' + index);
                    isFirstVisit = false;
                    isWindowPopped = true;
                    shouldPush = true;
                }
            };
        }

        window.onload = function(event) {
            var index = 1;
            if(history.state !== null && !(XMLHttpRequest)){ // ie's having problems with this
                index = history.state.page;
            }
            if($('.js-pagination')){
              //  initPagination(index);
                shouldPush = true;
            }
        };
    }


    var init = function() {
        // Patch for :checked state in IE8
        $('.lt-ie9 input[type="checkbox"]').on('change', function() {
            if ( $(this).prop('checked') ) {
                $(this).addClass('checked');
            } else {
                $(this).removeClass('checked');
            }
        });
        // Patch for :checked state on radios on IE8
        $('.lt-ie9 input[type="radio"]').on('change', function() {
            var name = $(this).attr('name');
            $('input[type="radio"][name="'+name+'"]').removeClass('checked');
            $('input[type="radio"][name="'+name+'"]:checked').addClass('checked');

        });

        /**
         * initialize global components
         */
        initGlobalComponents();

        /**
         * initialize components for the current page
         */
        initPageComponents();
        setBlurHeight();
        checkBackgroundBlendMode();
        bindEventsToUI();
        goBackHistory();

    };

    /**
     * interfaces to public functions
     */
    return {
        init: init
    };

}());

$( document ).ready( APP.global.init );

